using System.Collections.Generic;
using LittleLeo;
using NaughtyAttributes;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "EnhanceAction", menuName = "Data/Battle/Battle Actions/Moonie/Enhance Action")]
public class EnhanceAction : ChooseDiceAction
{
	[Header("Action Specifics")]
	[SerializeField]
	protected int newActionValue;

	[SerializeField]
	private bool enhanceAction;

	[SerializeField]
	private bool brightEnhancement;

	[SerializeField]
	private bool amplifyInsight;

	[SerializeField]
	[ShowIf("amplifyInsight")]
	private float amplifyInsightVFXDelay;

	[SerializeField]
	private bool useOnEnemiesAndCompanions;

	[SerializeField]
	[ShowIf("useOnEnemiesAndCompanions")]
	protected CurrentCorruptedAnimals currentCorruptedAnimals;

	[SerializeField]
	[ShowIf("useOnEnemiesAndCompanions")]
	protected CurrentCompanions currentCompanions;

	[SerializeField]
	private bool enableEnhanceDelay;

	[SerializeField]
	[ShowIf("enableEnhanceDelay")]
	private float enhanceDelay;

	[Header("Achievement")]
	[SerializeField]
	private bool enablePrestidigitationAchievementData;

	[SerializeField]
	[ShowIf("enablePrestidigitationAchievementData")]
	private AchievementData prestidigitationAchievementData;

	public int NewActionValueWithoutModifiers => newActionValue;

	public override bool CheckConditionToBeCasted(bool playerHand, DiceOwnerEnum diceOwnerEnum)
	{
		for (int i = 0; i < ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount(); i++)
		{
			if (CheckEnhance(ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInstanceFromHand(i)))
			{
				return true;
			}
		}
		if (useOnEnemiesAndCompanions)
		{
			for (int j = 0; j < currentCorruptedAnimals.activeCorruptedAnimals.Count; j++)
			{
				CorruptedAnimalActivation component = currentCorruptedAnimals.activeCorruptedAnimals[j].GetComponent<CorruptedAnimalActivation>();
				if (!component.BasicDiceSpawned)
				{
					continue;
				}
				DiceInstance basicDiceInstance = component.BasicDiceInstance;
				if (CheckEnhance(basicDiceInstance))
				{
					return true;
				}
				if (component.BoostDiceSpawned && component.IsBoosted)
				{
					DiceInstance boostDiceInstance = component.BoostDiceInstance;
					if (CheckEnhance(boostDiceInstance))
					{
						return true;
					}
				}
			}
			for (int k = 0; k < currentCompanions.ActiveCompanions.Count; k++)
			{
				CompanionAbility component2 = currentCompanions.ActiveCompanions[k].GetComponent<CompanionAbility>();
				DiceInstance basicDiceInstance2 = component2.BasicDiceInstance;
				if (basicDiceInstance2.ActionEnabled && CheckEnhance(basicDiceInstance2))
				{
					return true;
				}
				if (component2.IsBoosted)
				{
					DiceInstance boostDiceInstance2 = component2.BoostDiceInstance;
					if (boostDiceInstance2.ActionEnabled && CheckEnhance(boostDiceInstance2))
					{
						return true;
					}
				}
			}
		}
		return false;
	}

	private bool CheckEnhance(DiceInstance diceInstance)
	{
		ActionFace actionFace = diceInstance.ActionFace;
		if (actionFace.BattleAction is PurifyAction)
		{
			if (amplifyInsight)
			{
				if (diceInstance.ActionFace.ActionValue == 1)
				{
					return true;
				}
				return false;
			}
			return true;
		}
		if (actionFace.EnableSecondAction && actionFace.SecondBattleAction is PurifyAction)
		{
			if (amplifyInsight)
			{
				if (diceInstance.ActionFace.SecondActionValue == 1)
				{
					return true;
				}
				return false;
			}
			return true;
		}
		return false;
	}

	public override bool CheckCondition(DiceInstance diceInstance)
	{
		return CheckEnhance(diceInstance);
	}

	public override void Cast(GameObject source)
	{
		if (diceList.Count == 0)
		{
			for (int i = 0; i < ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInHandAmount(); i++)
			{
				diceList.Add(ReferenceSingleton<PlayerDiceHandHolder>.Instance.GetDiceInstanceFromHand(i));
			}
			DefaultCast(goBackToDiceTray: false);
		}
		else
		{
			DefaultCast(goBackToDiceTray: true);
		}
	}

	private void DefaultCast(bool goBackToDiceTray)
	{
		ReferenceSingleton<GameStateManager>.Instance.SetNoInteractionState();
		new List<OmenInstance>();
		int diceRefinedAmount = 0;
		List<MoonieOmensHandler.DiceInstanceEnhanced> diceEnhancedList = new List<MoonieOmensHandler.DiceInstanceEnhanced>();
		for (int i = 0; i < diceList.Count; i++)
		{
			bool flag = false;
			DiceInstance diceInstance = diceList[i];
			bool flag2 = false;
			bool flag3 = false;
			if (diceInstance.ActionFace.BattleAction is PurifyAction)
			{
				if (amplifyInsight)
				{
					if (diceInstance.ActionFace.ActionValue == 1)
					{
						flag = true;
						flag2 = true;
					}
				}
				else
				{
					if (enhanceAction)
					{
						int num = diceRefinedAmount;
						diceRefinedAmount = num + 1;
						diceEnhancedList.Add(new MoonieOmensHandler.DiceInstanceEnhanced(diceInstance, diceInstance.ActionFace.ActionValue, diceInstance.ActionFace.SecondActionValue));
					}
					flag = true;
					flag2 = true;
				}
			}
			if (diceInstance.ActionFace.EnableSecondAction && diceInstance.ActionFace.SecondBattleAction is PurifyAction)
			{
				if (amplifyInsight)
				{
					if (diceInstance.ActionFace.SecondActionValue == 1)
					{
						flag = true;
						flag3 = true;
					}
				}
				else
				{
					if (enhanceAction)
					{
						int num = diceRefinedAmount;
						diceRefinedAmount = num + 1;
						diceEnhancedList.Add(new MoonieOmensHandler.DiceInstanceEnhanced(diceInstance, diceInstance.ActionFace.ActionValue, diceInstance.ActionFace.SecondActionValue));
					}
					flag = true;
					flag3 = true;
				}
			}
			if (flag2 && flag3)
			{
				EnhanceBothActions(diceInstance);
			}
			else if (flag2)
			{
				EnhanceFirstAction(diceInstance);
			}
			else if (flag3)
			{
				EnhanceSecondAction(diceInstance);
			}
			if (enablePrestidigitationAchievementData && !prestidigitationAchievementData.IsUnlocked() && diceInstance.DiceOwnerEnum == DiceOwnerEnum.ENEMY)
			{
				prestidigitationAchievementData.Unlock();
			}
			if (enhanceAction && flag)
			{
				if (IsVFXEnabled())
				{
					if (enableEnhanceDelay && !brightEnhancement)
					{
						InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, enhanceDelay, delegate
						{
							SpawnVFXAndUpdateDiceInstance(goBackToDiceTray, i, diceInstance, diceRefinedAmount, diceEnhancedList);
						});
					}
					else
					{
						SpawnVFXAndUpdateDiceInstance(goBackToDiceTray, i, diceInstance, diceRefinedAmount, diceEnhancedList);
					}
				}
				else
				{
					SpawnVFXAndUpdateDiceInstance(goBackToDiceTray, i, diceInstance, diceRefinedAmount, diceEnhancedList);
				}
			}
			else if (flag)
			{
				SpawnVFXAndUpdateDiceInstance(goBackToDiceTray, i, diceInstance, diceRefinedAmount, diceEnhancedList);
			}
		}
		PlaySFX();
		SpawnSecondVFXOnPlayerPosition(6f);
		PlaySecondSFXWithDelay(diceList.Duplicate());
		if (IsVFXEnabled())
		{
			if (enableEnhanceDelay)
			{
				if (brightEnhancement)
				{
					ReferenceSingleton<PlayerDiceHandPositioningAnimationManager>.Instance.UpdateDiceInHandPosition();
				}
				if (!enableEnhanceDelay)
				{
					return;
				}
				InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, enhanceDelay, delegate
				{
					if (brightEnhancement)
					{
						for (int j = 0; j < diceList.Count; j++)
						{
							SpawnVFXAndUpdateDiceInstance(diceList[j]);
						}
						bool flag4 = amplifyInsight || brightEnhancement;
						EndOfActionActivateEffectsOmensAndReset(!flag4, diceRefinedAmount, diceEnhancedList);
					}
					else
					{
						EndOfActionActivateEffectsOmensAndReset(goBackToDiceTray, diceRefinedAmount, diceEnhancedList);
					}
				});
			}
			else if (amplifyInsight && amplifyInsightVFXDelay > 0f)
			{
				ReferenceSingleton<PlayerDiceHandPositioningAnimationManager>.Instance.UpdateDiceInHandPosition();
			}
			else
			{
				EndOfActionActivateEffectsOmensAndReset(goBackToDiceTray, diceRefinedAmount, diceEnhancedList);
			}
		}
		else
		{
			EndOfActionActivateEffectsOmensAndReset(goBackToDiceTray, diceRefinedAmount, diceEnhancedList);
		}
	}

	protected virtual void PlaySecondSFXWithDelay(List<DiceInstance> diceList)
	{
	}

	private void SpawnVFXAndUpdateDiceInstance(bool goBackToDiceTray, int i, DiceInstance diceInstance, int diceRefinedAmount, List<MoonieOmensHandler.DiceInstanceEnhanced> diceEnhancedList)
	{
		if (goBackToDiceTray)
		{
			if (IsVFXEnabled())
			{
				if (brightEnhancement && enableEnhanceDelay)
				{
					SetDiceInstanceGoBackToOriginalPositionAnimation(goBackToDiceTray, i, diceInstance, null, dontTryToGoToChooseActionState: true);
				}
				else if (amplifyInsight && amplifyInsightVFXDelay > 0f)
				{
					SetDiceInstanceGoBackToOriginalPositionAnimation(goBackToDiceTray, i, diceInstance, delegate
					{
						GetVFX(4f).GetComponent<ParticleFollower>().Initialize(diceInstance);
						InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, amplifyInsightVFXDelay, delegate
						{
							for (int j = 0; j < diceList.Count; j++)
							{
								diceList[j].UpdateDiceFace();
							}
							EndOfActionActivateEffectsOmensAndReset(goBackToDiceTray: false, diceRefinedAmount, diceEnhancedList);
						});
					}, dontTryToGoToChooseActionState: true);
				}
				else
				{
					SetDiceInstanceGoBackToOriginalPositionAnimation(goBackToDiceTray, i, diceInstance, delegate
					{
						SpawnVFXAndUpdateDiceInstance(diceInstance);
					});
				}
			}
			else
			{
				SetDiceInstanceGoBackToOriginalPositionAnimation(goBackToDiceTray, i, diceInstance, delegate
				{
					SpawnVFXAndUpdateDiceInstance(diceInstance);
				});
			}
		}
		else
		{
			SpawnVFXAndUpdateDiceInstance(diceInstance);
		}
	}

	private void SpawnVFXAndUpdateDiceInstance(DiceInstance diceInstance)
	{
		if (IsVFXEnabled())
		{
			GetVFX(4f).GetComponent<ParticleFollower>().Initialize(diceInstance);
		}
		diceInstance.UpdateDiceFace();
	}

	private void EndOfActionActivateEffectsOmensAndReset(bool goBackToDiceTray, int diceRefinedAmount, List<MoonieOmensHandler.DiceInstanceEnhanced> diceEnhancedList)
	{
		EndAction(goBackToDiceTray);
		if (enhanceAction)
		{
			ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.AddEnhancedDiceAmount(diceRefinedAmount);
			ReferenceSingleton<MoonieOmensHandler>.Instance.ActivateEnhanceOmens(diceEnhancedList);
		}
		ResetVariables();
	}

	protected virtual void EnhanceFirstAction(DiceInstance diceInstance)
	{
		diceInstance.ActionFace.ActionValue = FinalValue(diceInstance);
	}

	protected virtual void EnhanceSecondAction(DiceInstance diceInstance)
	{
		diceInstance.ActionFace.SecondActionValue = FinalValue(diceInstance);
	}

	protected virtual void EnhanceBothActions(DiceInstance diceInstance)
	{
		int num = FinalValue(diceInstance);
		diceInstance.ActionFace.ActionValue = num;
		diceInstance.ActionFace.SecondActionValue = num;
	}

	public int FinalValue(DiceInstance diceInstance)
	{
		return GetFinalValueWithoutLunarAnomalyOmen(activateFeedback: false) * ReferenceSingleton<MoonieOmensHandler>.Instance.IsLunarSingularityActiveGetMultiplier(diceInstance);
	}

	private int GetFinalValueWithoutLunarAnomalyOmen(bool activateFeedback)
	{
		int num = 0;
		if (base.isOnBattleScene && !ReferenceSingleton<GameStateManager>.Instance.IsOnPlayerUnlockablesState)
		{
			num = ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().IsPlayerResearchGetAmount(activateFeedback);
		}
		return newActionValue + num;
	}

	public int FinalValueForTag(bool activateFeedback)
	{
		return GetFinalValueWithoutLunarAnomalyOmen(activateFeedback);
	}

	public string GetResearchModifierText()
	{
		int num = 0;
		if (base.isOnBattleScene && !ReferenceSingleton<GameStateManager>.Instance.IsOnPlayerUnlockablesState)
		{
			num = ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<PlayerEffects>().IsPlayerResearchGetAmount(activateFeedback: false);
		}
		string result = "";
		if (num > 0)
		{
			result = $" ({newActionValue}+{num})";
		}
		return result;
	}
}
